const menuBold = (text) => {
    const up = '𝗔𝗕𝗖𝗗𝗘𝗙𝗚𝗛𝗜𝗝𝗞𝗟𝗠𝗡𝗢𝗣𝗤𝗥𝗦𝗧𝗨𝗩𝗪𝗫𝗬𝗭';
    const lo = '𝗮𝗯𝗰𝗱𝗲𝗳𝗴𝗵𝗶𝗷𝗸𝗹𝗺𝗻𝗼𝗽𝗾𝗿𝘀𝘁𝘂𝘃𝘄𝘅𝘆𝘇';
    const di = '𝟬𝟭𝟮𝟯𝟰𝟱𝟲𝟳𝟴𝟵';
    return [...String(text)].map(c => {
        if (c >= 'A' && c <= 'Z') return [...up][c.charCodeAt(0) - 65];
        if (c >= 'a' && c <= 'z') return [...lo][c.charCodeAt(0) - 97];
        if (c >= '0' && c <= '9') return [...di][c.charCodeAt(0) - 48];
        return c;
    }).join('');
};

const onOff = (v) => (v ? '🟢' : '🔴');

function section(icon, title, items) {
    return `\n┏━━ ${icon} ${menuBold(title)}\n` +
        items.map(i => `┃ ▸ ${i}`).join('\n') +
        `\n┗━━━━━━━━━━━━━━━━━━`;
}

function uptime() {
    const s = Math.floor(process.uptime());
    const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);
    return `${d ? d + 'd ' : ''}${h}h ${m}m`;
}

function buildMenu({ userName, isPublic, aiEnabled, autoReact, antiDelete, autoStatus }) {
    const head =
`╔═══════════════════╗
   ⚡ ${menuBold(settings.botName)} ⚡
   ${menuBold('by ' + settings.company)}
╚═══════════════════╝

👤 ${menuBold('User')}    ›  ${userName}
👑 ${menuBold('Owner')}   ›  ${settings.ownerName}
🛰 ${menuBold('Mode')}    ›  ${isPublic ? 'Public 🌍' : 'Private 🔐'}
⏱ ${menuBold('Uptime')}  ›  ${uptime()}
🔰 ${menuBold('Prefix')}  ›  [ . ]`;

    const user = section('🧩', 'Essentials', [
        '.autoreacts [on/off]', '.antilink [on/off/kick]', '.antidelete [on/off]',
        '.ai [on/off]', '.vv', '.owner', '.dp', '.ping', '.translate (text)'
    ]);
    const tools = section('📥', 'Downloads & Fun', [
        '.apk (name)', '.facebook (url)', '.tiktok (url)', '.insta (url)', '.song (name)',
        '.video (name)', '.gdrive (url)', '.mf (url)', '.joke', '.meme',
        '.emojimix (e1+e2)', '.character (mention)'
    ]);
    const admin = section('🛡', 'Admin Zone', [
        '.private', '.public', '.autoread [on/off]',
        '.status [on/off/seen/like/download/system]', '.hack', '.hidetag', '.tagall',
        '.setname (name)', '.anticall [on/off]', '.kickoffline [on/off]',
        '.antistatus [on/off]', '.groupinfo', '.accept'
    ]);

    const live =
`\n┏━━ 📡 ${menuBold('Live Status')}
┃ ${onOff(aiEnabled)} AI   ${onOff(autoReact)} Auto-React
┃ ${onOff(antiDelete)} Anti-Delete   ${onOff(autoStatus)} Auto-Status
┗━━━━━━━━━━━━━━━━━━`;

    const channel = settings.channelLink ? `\n🔗 ${menuBold('Channel')}\n> ${settings.channelLink}` : '';
    const foot = `${channel}\n\n⚡ _${settings.botName} • ${settings.company}_`;

    return [head, user, tools, admin, live].join('\n') + foot;
}


