__defs["commands/accept.js"] = function (module, exports, require, __filename, __dirname) {
async function acceptCommand(sock, from, msg, isAdmin) {
    if (!from.endsWith('@g.us')) {
        return sock.sendMessage(from, { text: '❌ This command can only be used in groups.' }, { quoted: msg });
    }

    if (!isAdmin) {
        return sock.sendMessage(from, { text: '❌ Only group admins can use this command.' }, { quoted: msg });
    }

    try {
        // Fetch pending join requests
        const response = await sock.groupRequestParticipantsList(from);
        
        if (!response || response.length === 0) {
            return sock.sendMessage(from, { text: '✅ No pending join requests found in this group.' }, { quoted: msg });
        }

        await sock.sendMessage(from, { text: `⏳ Found ${response.length} pending requests. Starting auto-accept...` }, { quoted: msg });

        let acceptedCount = 0;
        for (const participant of response) {
            try {
                await sock.groupRequestParticipantsUpdate(from, [participant.jid], 'approve');
                acceptedCount++;
                // Small delay to prevent rate limiting
                await new Promise(resolve => setTimeout(resolve, 2000));
            } catch (err) {
                console.error(`Failed to accept ${participant.jid}:`, err.message);
            }
        }

        await sock.sendMessage(from, { text: `✅ Successfully accepted ${acceptedCount} pending requests.` }, { quoted: msg });

    } catch (e) {
        console.error('Accept command error:', e);
        await sock.sendMessage(from, { text: '❌ Error: ' + e.message }, { quoted: msg });
    }
}

module.exports = acceptCommand;

};
__defs["commands/ai.js"] = function (module, exports, require, __filename, __dirname) {
async function aiCommand(sock, from, msg, isAdmin, session, args) {
    if (!isAdmin) return await sock.sendMessage(from, { text: "❌ Only owner can use this command." }, { quoted: msg });
    
    const action = args[0]?.toLowerCase();
    if (action === 'on') {
        session.aiEnabled = true;
        await sock.sendMessage(from, { text: "✅ AI Auto-Reply Enabled!" }, { quoted: msg });
    } else if (action === 'off') {
        session.aiEnabled = false;
        await sock.sendMessage(from, { text: "❌ AI Auto-Reply Disabled!" }, { quoted: msg });
    } else if (args.length > 0) {
        // Direct query to AI
        const query = args.join(' ');
        try {
            await sock.sendMessage(from, { react: { text: '🤖', key: msg.key } });
            const response = await session.getAIResponse(from, query);
            await sock.sendMessage(from, { text: response }, { quoted: msg });
        } catch (e) {
            await sock.sendMessage(from, { text: "❌ AI Error: " + e.message }, { quoted: msg });
        }
    } else {
        await sock.sendMessage(from, { text: "❌ Usage:\n.ai [on/off] - Toggle Auto-Reply\n.ai [query] - Ask AI something" }, { quoted: msg });
    }
}

module.exports = aiCommand;

};
