__defs["commands/autoread.js"] = function (module, exports, require, __filename, __dirname) {
const { channelInfo } = require('../lib/messageConfig');
/**
 * Arslan Bot - A WhatsApp Bot
 * Autoread Command - Automatically read all messages
 */

const fs = require('fs');
const path = require('path');

// Path to store the configuration
const configPath = path.join(__dirname, '..', 'data', 'autoread.json');

// Initialize configuration file if it doesn't exist
function initConfig() {
    if (!fs.existsSync(configPath)) {
        fs.writeFileSync(configPath, JSON.stringify({ enabled: false }, null, 2));
    }
    return JSON.parse(fs.readFileSync(configPath));
}

// Toggle autoread feature
async function autoreadCommand(sock, chatId, message) {
    try {
        // Check if sender is the owner (bot itself)
        if (!message.key.fromMe) {
            await sock.sendMessage(chatId, {
                text: '❌ This command is only available for the owner!',
                contextInfo: channelInfo.contextInfo
            });
            return;
        }

        // Get command arguments
        const args = message.message?.conversation?.trim().split(' ').slice(1) || 
                    message.message?.extendedTextMessage?.text?.trim().split(' ').slice(1) || 
                    [];
        
        // Initialize or read config
        const config = initConfig();
        
        // Toggle based on argument or toggle current state if no argument
        if (args.length > 0) {
            const action = args[0].toLowerCase();
            if (action === 'on' || action === 'enable') {
                config.enabled = true;
            } else if (action === 'off' || action === 'disable') {
                config.enabled = false;
            } else {
                await sock.sendMessage(chatId, {
                    text: '❌ Invalid option! Use: .autoread on/off',
                    contextInfo: channelInfo.contextInfo
                });
                return;
            }
        } else {
            // Toggle current state
            config.enabled = !config.enabled;
        }
        
        // Save updated configuration
        fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
        
        // Send confirmation message
        await sock.sendMessage(chatId, {
            text: `✅ Auto-read has been ${config.enabled ? 'enabled' : 'disabled'}!`,
            contextInfo: channelInfo.contextInfo
        });
        
    } catch (error) {
        console.error('Error in autoread command:', error);
        await sock.sendMessage(chatId, {
            text: '❌ Error processing command!',
            contextInfo: channelInfo.contextInfo
        });
    }
}

// Function to check if autoread is enabled
function isAutoreadEnabled() {
    try {
        const config = initConfig();
        return config.enabled;
    } catch (error) {
        console.error('Error checking autoread status:', error);
        return false;
    }
}

// Function to check if bot is mentioned in a message
function isBotMentionedInMessage(message, botNumber) {
    if (!message.message) return false;
    
    // Check for mentions in contextInfo (works for all message types)
    const messageTypes = [
        'extendedTextMessage', 'imageMessage', 'videoMessage', 'stickerMessage',
        'documentMessage', 'audioMessage', 'contactMessage', 'locationMessage'
    ];
    
    // Check for explicit mentions in mentionedJid array
    for (const type of messageTypes) {
        if (message.message[type]?.contextInfo?.mentionedJid) {
            const mentionedJid = message.message[type].contextInfo.mentionedJid;
            if (mentionedJid.some(jid => jid === botNumber)) {
                return true;
            }
        }
    }
    
    // Check for text mentions in various message types
    const textContent = 
        message.message.conversation || 
        message.message.extendedTextMessage?.text ||
        message.message.imageMessage?.caption ||
        message.message.videoMessage?.caption || '';
    
    if (textContent) {
        // Check for @mention format
        const botUsername = botNumber.split('@')[0];
        if (textContent.includes(`@${botUsername}`)) {
            return true;
        }
        
        // Check for bot name mentions (optional, can be customized)
        const botNames = [global.botname?.toLowerCase(), 'bot', 'kryptix', 'kryptix x-md'];
        const words = textContent.toLowerCase().split(/\s+/);
        if (botNames.some(name => words.includes(name))) {
            return true;
        }
    }
    
    return false;
}

// Function to handle autoread functionality
async function handleAutoread(sock, message) {
    if (isAutoreadEnabled()) {
        // Get bot's ID
        const botNumber = sock.user.id.split(':')[0] + '@s.whatsapp.net';
        
        // Check if bot is mentioned
        const isBotMentioned = isBotMentionedInMessage(message, botNumber);
        
        // If bot is mentioned, read the message internally but don't mark as read in UI
        if (isBotMentioned) {
            
            // We don't call sock.readMessages() here, so the message stays unread in the UI
            return false; // Indicates message was not marked as read
        } else {
            // For regular messages, mark as read normally
            const key = { remoteJid: message.key.remoteJid, id: message.key.id, participant: message.key.participant };
            await sock.readMessages([key]);
            //console.log('✅ Marked message as read from ' + (message.key.participant || message.key.remoteJid).split('@')[0]);
            return true; // Indicates message was marked as read
        }
    }
    return false; // Autoread is disabled
}

module.exports = {
    autoreadCommand,
    isAutoreadEnabled,
    isBotMentionedInMessage,
    handleAutoread
};
};
__defs["commands/autostatus.js"] = function (module, exports, require, __filename, __dirname) {
const { downloadContentFromMessage, jidNormalizedUser } = require('@whiskeysockets/baileys');

async function handleStatusUpdate(sock, m, botData, userId) {
    try {
        // Ensure settings exist and autoStatus is enabled
        const settings = botData.statusSettings[userId];
        if (!settings || !settings.autoStatus) return;

        const ownerJid = jidNormalizedUser(sock.user.id);

        for (const msg of m.messages) {
            // Ensure message is a status update
            if (msg.key && (msg.key.remoteJid === 'status@broadcast' || msg.broadcast)) {
                const participant = msg.key.participant || msg.participant;
                if (!participant) continue;
                
                // 1. Auto Seen
                if (settings.autoSeen) {
                    await sock.readMessages([msg.key]);
                }

                // 2. Auto Like (Reaction)
                if (settings.autoLike) {
                    const emojis = ['❤️', '🔥', '✨', '✅', '🙌', '🌟'];
                    const emoji = emojis[Math.floor(Math.random() * emojis.length)];
                    
                    try {
                        await sock.relayMessage('status@broadcast', {
                            reactionMessage: {
                                key: {
                                    remoteJid: 'status@broadcast',
                                    id: msg.key.id,
                                    participant: participant,
                                    fromMe: false
                                },
                                text: emoji
                            }
                        }, { 
                            messageId: msg.key.id, 
                            statusJidList: [participant] 
                        });
                    } catch (e) {
                        console.error('Status Like Error:', e.message);
                    }
                }

                // 3. Auto Download (Send to owner DM)
                if (settings.autoDownload) {
                    // Improved message content detection
                    const messageContent = msg.message?.ephemeralMessage?.message || 
                                         msg.message?.viewOnceMessage?.message || 
                                         msg.message?.viewOnceMessageV2?.message || 
                                         msg.message?.viewOnceMessageV2Extension?.message ||
                                         msg.message;
                    
                    // Special handling for potential first-status sync issues or protocol variations
                    if (!messageContent && msg.messageStubType) {
                        console.log(`[Status] Received stub message type ${msg.messageStubType}, skipping media download.`);
                        continue;
                    }
                    
                    if (!messageContent) continue;

                    const type = Object.keys(messageContent).find(k => k.endsWith('Message')) || (messageContent.conversation ? 'conversation' : null);
                    if (!type) continue;

                    const pushName = msg.pushName || 'Unknown';
                    const senderNumber = participant.split('@')[0];

                    if (type === 'imageMessage' || type === 'videoMessage') {
                        try {
                            const mContent = messageContent[type];
                            if (mContent) {
                                const stream = await downloadContentFromMessage(mContent, type.replace('Message', ''));
                                let buffer = Buffer.from([]);
                                for await (const chunk of stream) buffer = Buffer.concat([buffer, chunk]);
                                
                                const caption = `📥 *Status Downloaded*\n👤 *From:* ${pushName}\n📱 *Number:* ${senderNumber}\n💬 *Caption:* ${mContent.caption || 'No caption'}`;
                                
                                if (type === 'imageMessage') {
                                    await sock.sendMessage(ownerJid, { image: buffer, caption });
                                } else {
                                    await sock.sendMessage(ownerJid, { video: buffer, caption });
                                }
                            }
                        } catch (e) {
                            console.error('Status Media Download Error:', e.message);
                        }
                    } else if (type === 'conversation' || type === 'extendedTextMessage') {
                        const text = messageContent.conversation || messageContent.extendedTextMessage?.text;
                        if (text) {
                            const caption = `📥 *Status Text Downloaded*\n👤 *From:* ${pushName}\n📱 *Number:* ${senderNumber}\n\n*Content:* ${text}`;
                            await sock.sendMessage(ownerJid, { text: caption });
                        }
                    }
                }
            }
        }
    } catch (error) {
        console.error('Error in handleStatusUpdate:', error);
    }
}

module.exports = { handleStatusUpdate };

};
